<script setup lang="ts">
import { Head, Link, router } from '@inertiajs/vue3'
import { reactive, ref } from 'vue'
import AuthenticatedLayout from '../../../Layouts/AuthenticatedLayout.vue'
import { useAccountGridPreferences, type GridColumnDefinition, type GridPreferenceValue } from '../../../Composables/useAccountGridPreferences'
type Row = { id:number; email:string; first_name:string|null; last_name:string|null; providers:string|null; source_sites:string|null; statuses:string|null; lists:string|null; latest_subscribed_at:string|null; latest_unsubscribed_at:string|null; latest_synced_at:string|null }
type Paginator = { data: Row[]; current_page:number; last_page:number; total:number; links:{url:string|null;label:string;active:boolean}[] }
type ColumnKey = 'email'|'name'|'status'|'provider'|'source_site'|'list'|'subscribed_at'|'unsubscribed_at'|'last_synced_at'
const props = defineProps<{ subscribers: Paginator; filters: Record<string,string>; filterOptions:{statuses:string[];providers:string[];source_sites:string[]}; gridPreference: GridPreferenceValue<ColumnKey>|null }>()
const definitions: GridColumnDefinition<ColumnKey>[] = [{key:'email',label:'Email'},{key:'name',label:'姓名'},{key:'status',label:'当前状态'},{key:'provider',label:'Provider'},{key:'source_site',label:'来源站点'},{key:'list',label:'列表'},{key:'subscribed_at',label:'订阅日期'},{key:'unsubscribed_at',label:'退订日期'},{key:'last_synced_at',label:'最后同步'}]
const { columns, visibleColumns, toggle, startDrag, drop, reset } = useAccountGridPreferences<ColumnKey>({ namespace:'grid.marketing.subscribers.v1', definitions, serverValue:props.gridPreference })
const filters = reactive({ search:props.filters.search??'', status:props.filters.status??'', provider:props.filters.provider??'', source_site:props.filters.source_site??'' }); const settingsOpen=ref(false)
const applyFilters=()=>router.get('/marketing/subscribers', Object.fromEntries(Object.entries(filters).filter(([,v])=>v)), {preserveState:true,replace:true})
const date=(v:string|null)=>v?v.slice(0,10):'—'; const name=(r:Row)=>[r.first_name,r.last_name].filter(Boolean).join(' ')||'—'; const display=(v:string|null)=>v?v.split(',').join(', '):'—'
</script>
<template>
<Head title="邮件订阅 · BYL ERP" /><AuthenticatedLayout title="邮件订阅" :breadcrumbs="['BYL ERP','营销','邮件订阅']"><div class="erp-form-page"><div class="erp-form-content">
<div class="erp-form-header-row"><div><p class="mvp-kicker">MARKETING OS · READ ONLY</p><h1 class="erp-form-title">邮件订阅</h1><p class="erp-form-subtitle">按 provider/source 展示订阅事实；不同来源的订阅事实分别保留；subscribed 不代表全局允许发送 EDM。</p></div><div class="mvp-actions page-header-actions"><Link class="erp-btn erp-btn-primary" href="/sync/wpapi">同步 WP</Link></div></div>
<form class="subscriber-filters erp-form-card" @submit.prevent="applyFilters"><input v-model="filters.search" placeholder="搜索 Email 或姓名" aria-label="搜索 Email 或姓名"/><select v-model="filters.status" aria-label="订阅状态"><option value="">全部状态</option><option v-for="v in filterOptions.statuses" :key="v" :value="v">{{v}}</option></select><select v-model="filters.provider" aria-label="Provider"><option value="">全部 Provider</option><option v-for="v in filterOptions.providers" :key="v" :value="v">{{v}}</option></select><select v-model="filters.source_site" aria-label="来源站点"><option value="">全部来源站点</option><option v-for="v in filterOptions.source_sites" :key="v" :value="v">{{v}}</option></select><button class="erp-btn erp-btn-primary" type="submit">筛选</button></form>
<section class="erp-form-card subscriber-grid-card"><div class="grid-toolbar"><p>共 {{ subscribers.total }} 条订阅者身份</p><div class="column-settings"><button class="erp-btn erp-btn-secondary" type="button" aria-label="列设置" @click="settingsOpen=!settingsOpen">…</button><div v-if="settingsOpen" class="column-menu"><label v-for="column in columns" :key="column.key" draggable="true" @dragstart="startDrag(column.key)" @dragover.prevent @drop="drop(column.key)"><input type="checkbox" :checked="column.visible" @change="toggle(column.key)"/> {{column.label}}</label><button type="button" @click="reset">恢复默认</button></div></div></div><div v-if="!subscribers.data.length" class="mvp-empty">当前没有订阅者记录。此为空数据状态，系统未生成示例订阅者或同意记录。</div><div v-else class="grid-scroll"><table><thead><tr><th v-for="column in visibleColumns" :key="column.key">{{column.label}}</th></tr></thead><tbody><tr v-for="row in subscribers.data" :key="row.id"><td v-for="column in visibleColumns" :key="column.key"><template v-if="column.key==='email'">{{row.email}}</template><template v-else-if="column.key==='name'">{{name(row)}}</template><template v-else-if="column.key==='status'">{{display(row.statuses)}}</template><template v-else-if="column.key==='provider'">{{display(row.providers)}}</template><template v-else-if="column.key==='source_site'">{{display(row.source_sites)}}</template><template v-else-if="column.key==='list'">{{display(row.lists)}}</template><template v-else-if="column.key==='subscribed_at'">{{date(row.latest_subscribed_at)}}</template><template v-else-if="column.key==='unsubscribed_at'">{{date(row.latest_unsubscribed_at)}}</template><template v-else>{{date(row.latest_synced_at)}}</template></td></tr></tbody></table></div><nav v-if="subscribers.last_page>1" class="pagination" aria-label="分页"><Link v-for="link in subscribers.links" :key="link.label" :href="link.url??'#'" :class="{active:link.active}" v-html="link.label"/></nav></section>
</div></div></AuthenticatedLayout>
</template>
<style scoped>.subscriber-filters{display:flex;gap:10px;flex-wrap:wrap;margin-bottom:16px}.subscriber-filters input,.subscriber-filters select{min-height:38px;max-width:100%;padding:0 10px;border:1px solid #d8e0e3;border-radius:6px}.grid-toolbar{display:flex;justify-content:space-between;align-items:center;margin-bottom:12px}.grid-toolbar p{margin:0;color:#52646b}.grid-scroll{overflow-x:auto}table{width:100%;border-collapse:collapse;min-width:960px}th,td{text-align:left;padding:11px 12px;border-bottom:1px solid #e6ecee;white-space:nowrap}th{font-size:12px;color:#52646b}.column-settings{position:relative}.column-menu{position:absolute;right:0;z-index:2;background:#fff;border:1px solid #d8e0e3;border-radius:6px;padding:10px;box-shadow:0 8px 24px #14212620;min-width:180px}.column-menu label{display:block;padding:5px;cursor:grab}.column-menu button{margin-top:8px}.pagination{display:flex;gap:6px;margin-top:16px}.pagination a{padding:5px 9px;border:1px solid #d8e0e3;border-radius:4px}.pagination a.active{background:#142126;color:#fff}@media(max-width:640px){.subscriber-filters>*{width:100%;flex:1 0 100%}.grid-toolbar{gap:8px}.subscriber-grid-card,.erp-form-content{min-width:0}}</style>
